 "content": "from collections import deque

def transform(grid):
    """For each 2 replacing a cell inside a 3-rectangle, paint its 3x3 neighborhood 1."""
    h, w = len(grid), len(grid[0])
    seen = set()
    rectangles = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 3 and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            rectangles.append((min(y for y,x in cells), max(y for y,x in cells), min(x for y,x in cells), max(x for y,x in cells)))
    markers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and any(r0 <= r <= r1 and c0 <= c <= c1 for r0,r1,c0,c1 in rectangles):
                markers.append((r,c))
    out = [row[:] for row in grid]
    for r,c in markers:
        for y in range(max(0,r-1), min(h,r+2)):
            for x in range(max(0,c-1), min(w,c+2)):
                if grid[y][x] != 2:
                    out[y][x] = 1
    return out
