 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Connected 3-regions give the bounds of the solid rectangular fields.
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 3 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            boxes.append((min(y for y,x in cells), max(y for y,x in cells),
                          min(x for y,x in cells), max(x for y,x in cells)))

    markers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            n3 = sum(0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 3
                     for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)))
            inside = any(r0 <= r <= r1 and c0 <= c <= c1 for r0,r1,c0,c1 in boxes)
            boundary_hole = any(r0-1 <= r <= r1+1 and c0-1 <= c <= c1+1
                                for r0,r1,c0,c1 in boxes) and n3 >= 2
            if inside or boundary_hole:
                markers.append((r,c))

    out = [row[:] for row in grid]
    for r,c in markers:
        for rr in range(max(0,r-1), min(h,r+2)):
            for cc in range(max(0,c-1), min(w,c+2)):
                if grid[rr][cc] != 2:
                    out[rr][cc] = 1
    return out
